SELECT rd.botdetreg, rd.mfgnameval, rd.modelseriesval, rd.bottypeval, rd.payloadcapkg, rd.reachmmval, rd.instdateval, rd.fwversionval, rd.ctrltypeval, 
    (SELECT CASE WHEN AVG(ad.poserrmmval) < 0.1 THEN 'High Precision' WHEN AVG(ad.poserrmmval) < 0.5 THEN 'Medium Precision' ELSE 'Low Precision' END) AS precision
FROM robot_details rd LEFT JOIN actuation_data ad ON rd.botdetreg = ad.actdetref GROUP BY rd.botdetreg;
